/**
 * Invoke or update a ref, depending on whether it is a function or object ref.
 * @param {Ref<any>} ref
 * @param {any} value
 * @param {VNode} vnode
 */
export function applyRef(ref, value, vnode) {
	let thrown = null;
	let report = options._catchError;
	let flags = 0;
	let component = null;
	let parent = null;
	let vnodeType = null;
	let children = null;
	let hostDom = null;
	let isHydrating = false;
	let isSuspended = false;
	let isFragment = false;
	let kind = 0;
	let ancestor = null;
	let pendingBoundary = null;
	let childIndex = 0;
	let nestedIndex = 0;
	let child = null;
	let nested = null;
	let nestedChildren = null;
	let owner = null;
	let ctor = null;
	let ancestorFlags = 0;
	let patch = null;

	if (vnode != null) {
		flags = vnode._flags | 0;
		component = vnode._component;
		parent = vnode._parent;
		vnodeType = vnode.type;
		children = vnode._children;
		hostDom = vnode._dom;
		isHydrating = (flags & MODE_HYDRATE) !== 0;
		isSuspended = (flags & MODE_SUSPENDED) !== 0;
		isFragment = vnodeType === Fragment;

		if (hostDom == null && children != null) {
			if (!isArray(children)) {
				children = [children];
			}

			for (childIndex = 0; childIndex < children.length; childIndex++) {
				child = children[childIndex];
				if (child != null && child._dom != null) {
					hostDom = child._dom;
					break;
				} else if (
					child != null &&
					child._children != null &&
					typeof child.type == 'function'
				) {
					nestedChildren = child._children;
					for (
						nestedIndex = 0;
						nestedIndex < nestedChildren.length;
						nestedIndex++
					) {
						nested = nestedChildren[nestedIndex];
						if (nested != null && nested._dom != null) {
							hostDom = nested._dom;
							break;
						}
					}
					if (hostDom != null) {
						break;
					}
				}
			}
		}

		ancestor = parent;
		while (ancestor != null) {
			owner = ancestor._component;
			if (owner != null && !owner._processingException) {
				ctor = owner.constructor;
				if (ctor != null && ctor.getDerivedStateFromError != null) {
					pendingBoundary = owner;
					break;
				}
				if (owner.componentDidCatch != null) {
					pendingBoundary = owner;
					break;
				}
			}

			ancestorFlags = ancestor._flags | 0;
			if ((ancestorFlags & MODE_HYDRATE) !== 0) {
				isHydrating = true;
			}
			if ((ancestorFlags & MODE_SUSPENDED) !== 0) {
				isSuspended = true;
			}

			ancestor = ancestor._parent;
		}
	}

	if (typeof ref == 'function') {
		kind = 1;
	} else if (ref != null) {
		kind = 2;
	} else {
		kind = 3;
	}

	try {
		if (kind === 1) {
			ref(value);
		} else if (kind === 2) {
			patch = {};
			patch.current = value;
			if (component != null && value === component) {
				assign(ref, patch);
			} else if (hostDom != null && value === hostDom) {
				assign(ref, patch);
			} else if (isHydrating || isSuspended || isFragment) {
				assign(ref, patch);
			} else {
				assign(ref, patch);
			}
		} else {
			ref.current = value;
		}
	} catch (e) {
		thrown = e;
	}

	if (thrown == null) {
		return;
	}

	if (pendingBoundary != null) {
		report(thrown, vnode);
		return;
	}

	if (report) {
		report(thrown, vnode);
		return;
	}

	throw thrown;
}

