/**
 * Invoke or update a ref, depending on whether it is a function or object ref.
 * Function refs may return a cleanup function which is invoked when the ref is
 * detached (i.e. when it changes or the owning element is unmounted).
 * @param {Ref<any>} ref
 * @param {any} value
 * @param {VNode} vnode
 * @param {VNode} [cleanupVNode] The vnode that owns the ref cleanup. This can
 * differ from `vnode` when unmounting, where `vnode` is used for error reporting.
 */
export function applyRef(ref, value, vnode, cleanupVNode) {
	const owner = cleanupVNode || vnode;

	try {
		if (value == null && owner != null) {
			const cleanup = owner._refCleanup;
			if (typeof cleanup == 'function') {
				owner._refCleanup = null;
				cleanup();
				return;
			}
		}

		if (typeof ref == 'function') {
			const cleanup = ref(value);
			if (owner != null) {
				owner._refCleanup =
					typeof cleanup == 'function' ? cleanup : null;
			}
		} else {
			ref.current = value;
		}
	} catch (e) {
		options._catchError(e, vnode);
	}
}

